data.input:
const qs=[
 "open immersion invariant under isomorphism precomposition postcomposition",
 "MorphismProperty cancel_left_of_respectsIso",
 "IsOpenImmersion respects isomorphisms"
];
const rs=[];
for (const q of qs) rs.push(await tools.mcp__lean_lsp__lean_leansearch({query:q,num_results:12}));
rs.forEach((r,i)=>{text(`Q${i+1}`);text(r);});

